// ============================================================
// js/data/holidays.js
// 节日与生日系统 — 统一数据库
//
// 替换原来的三个文件：
//   js/core/calendar.js        → 日历数据 + 日历UI函数
//   js/data/holiday_events.js  → 庄园横幅剧情数据
//   js/holiday_manager.js      → 庄园横幅管理器
//
// 文件结构：
//   一、节日数据（FESTIVALS）     — 日历用，含介绍文字 + 游玩暗示
//   二、庄园剧情（HOLIDAY_STORIES）— 庄园横幅弹窗用，含分支剧情 + 经验变化
//   三、生日剧情                   — 专属 + 通用模板，含分支 + 属性变化
//   四、日历UI函数                 — openCalendar / renderCalendar 等
//   五、庄园横幅管理器（HolidayManager）
// ============================================================


// ============================================================
// 一、FESTIVALS — 日历节日数据
//
// story 字段：日历点击时显示的介绍文字
//   风格：介绍节日背景 + 有趣细节 + 暗示主人可以做什么
//   不涉及具体角色，保持通用
// ============================================================

